GO
CREATE PROCEDURE #LNSafeAmount @OrderId int,@NewAmount decimal(12,2)
AS
BEGIN
 SET NOCOUNT ON;
 SET XACT_ABORT ON;
 IF @@TRANCOUNT<>0 THROW 51100,'This lab procedure requires no outer transaction.',1;
 IF @NewAmount IS NULL OR @NewAmount<0 THROW 51101,'Amount must be nonnegative.',1;
 BEGIN TRY
  BEGIN TRAN;
  UPDATE #LNProcedureWork SET Amount=@NewAmount WHERE OrderId=@OrderId;
  IF @@ROWCOUNT<>1 THROW 51102,'Expected exactly one order.',1;
  COMMIT;
 END TRY
 BEGIN CATCH
  IF XACT_STATE()<>0 ROLLBACK;
  THROW;
 END CATCH;
END;
GO
